      sha256 "0570afa860b0cf5ade9e97fd2471d9945fc7a1058598f0936dbce17dc5dfeec6"
    else
      url "https://github.com/mumei-lang/mumei/releases/download/v0.6.11/mumei-x86_64-unknown-linux-gnu.tar.gz"
